          action: combinedIntent.action,
          disposition: "review",
          target: targetKeys.size === 1 ? resultTargets[0] ?? null : null,
          patch: {},
          delegateTo: combinedIntent.delegateTo,
          reason: "\u540C\u4E00\u6761\u4E3B\u4EBA\u6D88\u606F\u5305\u542B\u591A\u4E2A\u52A8\u4F5C\uFF0C\u4F46\u5B83\u4EEC\u6CA1\u6709\u5168\u90E8\u843D\u5230\u540C\u4E00\u4E2A\u53EF\u5B89\u5168\u4FEE\u6539\u7684\u6B63\u5F0F\u4EFB\u52A1\uFF0C\u4FDD\u7559\u5F85\u786E\u8BA4\u3002",
